/* Written by tools/build_film.mjs from narration/film.json: do not edit. Times are seconds. */
export const FILM = {"audio":"assets/audio/film.mp3","voice":"fr_FR-siwis-medium","length":510.82,"steps":[{"id":"aube","from":0,"arrive":0,"voice":1.2,"leave":11.48,"lines":[{"at":1.2,"end":4.13,"text":"Portivechju. Lettre à ceux qui reviennent.","quiet":true},{"at":4.98,"end":10.28,"text":"À vous qui portez ce pays dans un nom, dans une maison, ou simplement dans une façon de dire « là-bas ».","quiet":true}],"cues":{},"pins":{}},{"id":"maquette","from":11.48,"arrive":18.48,"voice":13.88,"leave":28.01,"lines":[{"at":13.88,"end":20.67,"text":"Pour comprendre comment cette ville est née, il faut d’abord l’effacer — ôter les maisons, les quais, et revenir à la pierre nue."},{"at":21.27,"end":23.52,"text":"Un vieux proverbe corse le dit mieux que nous."},{"at":23.82,"end":26.91,"text":"Chì và è volta, bon viaghju face.","sub":"Celui qui part et revient a fait un bon voyage.","kind":"proverb"}],"cues":{},"pins":{}},{"id":"rocher","from":28.01,"arrive":36.01,"voice":30.61,"leave":47.83,"lines":[{"at":30.61,"end":36.34,"text":"Un golfe profond, refermé sur lui-même, et au fond de l’eau, un éperon de porphyre rose."},{"at":36.69,"end":39.23,"text":"Derrière lui, la montagne se lève aussitôt."},{"at":39.73,"end":47.13,"text":"Portivechju, le port vieux. Six siècles avant notre ère, dit-on, des Grecs de Syracuse y mouillaient déjà."}],"cues":{},"pins":{}},{"id":"port-vieux","from":47.83,"arrive":53.83,"voice":49.23,"leave":68.66,"lines":[{"at":49.23,"end":56.3,"text":"Un port, mais pas de ville. La plaine est fertile, pourtant personne n’ose y dormir : les marais donnent la fièvre."},{"at":56.75,"end":62.81,"text":"L’hiver seulement, les bergers descendent avec leurs troupeaux. Dès les chaleurs, ils remontent."},{"at":63.26,"end":67.66,"text":"Ce va-et-vient entre la montagne et la mer, c’est le premier battement de ce pays."}],"cues":{},"pins":{}},{"id":"citadelle","from":68.66,"arrive":93.42,"voice":71.46,"leave":94.42,"lines":[{"at":71.46,"end":79.35,"text":"Les corsaires se cachent dans ce golfe. En 1539, Gênes veut leur fermer ce refuge et choisit la hauteur du rocher."},{"at":79.8,"end":86.39,"text":"De 1541 à 1544, les remparts montent autour de la butte, défendus par cinq bastions."},{"at":87.44,"end":90.2,"text":"Derrière eux, Gênes installe ses premiers colons."}],"cues":{},"pins":{"bastion":79.8}},{"id":"ventimiglia","from":94.42,"arrive":100.42,"voice":95.82,"leave":113.86,"lines":[{"at":95.82,"end":103.01,"text":"Mais la ville ne tient pas. Sampiero Corso la prend en 1564 ; l’année suivante, tout est rasé."},{"at":103.46,"end":107.32,"text":"Des familles de Vintimille la relèvent, puis repartent à leur tour."},{"at":107.77,"end":112.86,"text":"Les pierres résistent, trois fois reconstruites. Il ne manquait que des gens pour rester."}],"cues":{},"pins":{}},{"id":"ceux-d-en-haut","from":113.86,"arrive":121.86,"voice":116.46,"leave":132.04,"lines":[{"at":116.46,"end":123.47,"text":"Alors Gênes lève les yeux vers la montagne. Des familles d’en haut, de Quenza surtout, descendent habiter la citadelle."},{"at":123.97,"end":131.14,"text":"Les deux noms de cette lettre viennent aussi de là-haut — les Rocca Serra, de Serra-di-Scopamène ; les Abbatucci, de Zicavo."}],"cues":{},"pins":{}},{"id":"estive","from":132.04,"arrive":137.04,"voice":133.44,"leave":154.32,"lines":[{"at":133.44,"end":135.96,"text":"Ils tiennent la ville, mais jamais toute l’année."},{"at":136.36,"end":143.65,"text":"Chaque été, quand revient la fièvre, on ferme les volets et l’on remonte vers Quenza, Zonza, Levie, l’Ospédale."},{"at":144.05,"end":149.14,"text":"À l’automne, on redescend. Une ville qui survit parce qu’elle sait se vider."},{"at":149.69,"end":152.92,"text":"Ici, partir n’a jamais été le contraire d’appartenir."}],"cues":{},"pins":{}},{"id":"paoli","from":154.32,"arrive":162.32,"voice":156.92,"leave":179.21,"lines":[{"at":156.92,"end":165.7,"text":"1769. L’année même où l’on commence la première carte précise de ce rivage, le golfe voit le plus célèbre de ses départs."},{"at":166.2,"end":173.28,"text":"Le 13 juin, vaincu à Ponte Novu, Pasquale Paoli embarque ici sur un navire anglais, direction l’exil."},{"at":173.73,"end":176.61,"text":"Quelque trois cents fidèles prennent la mer avec lui."}],"cues":{"sail":166.2},"pins":{}},{"id":"abbatucci","from":179.21,"arrive":185.21,"voice":180.61,"leave":208.85,"lines":[{"at":180.61,"end":184.58,"text":"L’homme qui a couvert sa retraite vient de Zicavo — Jacques Pierre Abbatucci."},{"at":184.88,"end":188.73,"text":"Paoli l’avait autrefois fait emprisonner, avant de lui confier tout le Sud."},{"at":189.13,"end":192.77,"text":"Dans la mémoire de la famille, c’est lui qui l’escorte jusqu’à ce port."},{"at":193.37,"end":200.55,"text":"Paoli reviendra vingt et un ans plus tard. Mais Jean-Charles, le fils du vieux général, ne rentrera jamais."},{"at":200.95,"end":207.45,"text":"Général à son tour, il tombe à vingt-six ans devant Huningue. Son nom est gravé sous l’Arc de triomphe."}],"cues":{},"pins":{"jp":180.61,"jc":193.37}},{"id":"sel","from":208.85,"arrive":215.85,"voice":211.45,"leave":223.79,"lines":[{"at":211.45,"end":217.61,"text":"Là où le Stabiacciu rejoint le golfe, l’eau dort dans les marais. Gênes y avait toujours interdit le sel."},{"at":218.01,"end":223.09,"text":"En 1795, les Rocca Serra reçoivent enfin le droit d’y aménager des salines."}],"cues":{},"pins":{}},{"id":"sauniers","from":223.79,"arrive":229.79,"voice":225.19,"leave":244.83,"lines":[{"at":225.19,"end":230.93,"text":"On y récoltera le sel deux siècles durant, jusqu’en l’an 2000 — les dernières salines de l’île."},{"at":231.38,"end":236.39,"text":"En 1803, le nom entre aussi à la mairie, pour y rester presque sans interruption."},{"at":236.94,"end":243.53,"text":"Le sel conserve ce qu’on lui confie. L’eau calme qui ouvre cette lettre, c’est celle de ces bassins."}],"cues":{},"pins":{"plan":225.19}},{"id":"liege","from":244.83,"arrive":251.83,"voice":247.43,"leave":263.09,"lines":[{"at":247.43,"end":256.88,"text":"Un siècle passe. Sur la Marine, dès 1876, une usine travaille le liège des collines — bouchons, flotteurs, isolants."},{"at":257.33,"end":262.39,"text":"On lève l’écorce au cœur de juillet, sous la chaleur lourde, quand il faudrait déjà être en montagne."}],"cues":{},"pins":{}},{"id":"ecorce","from":263.09,"arrive":268.09,"voice":264.49,"leave":282.65,"lines":[{"at":264.49,"end":273.03,"text":"Le chêne-liège se laisse dépouiller sans mourir. Nu, son tronc rougeoyant affronte le soleil ; dix à douze ans plus tard, l’écorce est revenue."},{"at":273.53,"end":281.45,"text":"L’usine ferme en 1975, vaincue par le plastique. Aujourd’hui, entre ses murs, on joue du théâtre."}],"cues":{},"pins":{}},{"id":"train","from":282.65,"arrive":292.65,"voice":286.65,"leave":302.47,"lines":[{"at":286.65,"end":292.09,"text":"En 1935, le train atteint enfin Porto-Vecchio, à cinq heures de Bastia."},{"at":293.29,"end":301.27,"text":"Il ne connaîtra que huit étés. En septembre 1943, les bombardements coupent la voie. Elle ne rouvrira jamais."}],"cues":{"train":286.65},"pins":{}},{"id":"fievre","from":302.47,"arrive":310.47,"voice":305.07,"leave":321.69,"lines":[{"at":305.07,"end":313.39,"text":"Voici l’anse au lendemain de la guerre, encore sauvage. Le mal qui vidait cette plaine depuis quatre siècles vient tout juste de céder."},{"at":313.84,"end":320.99,"text":"Entre les deux guerres déjà, le maire d’alors, le docteur Camille de Rocca Serra, avait appuyé la lutte contre le paludisme."}],"cues":{},"pins":{}},{"id":"rivage-1975","from":321.69,"arrive":327.69,"voice":323.09,"leave":341.52,"lines":[{"at":323.09,"end":328.46,"text":"Au printemps 1949, l’État lance sa campagne contre les moustiques par Porto-Vecchio."},{"at":328.81,"end":332.02,"text":"En deux ans, la fièvre s’effondre presque à zéro."},{"at":332.67,"end":340.52,"text":"En 1950, le fils de Camille, Jean-Paul, médecin lui aussi, devient maire. Il le restera quarante-sept ans."}],"cues":{},"pins":{"analyses":328.81}},{"id":"rivage-2024","from":341.52,"arrive":347.52,"voice":342.92,"leave":356,"lines":[{"at":342.92,"end":348.11,"text":"Les digues s’avancent, les quais s’ouvrent. Une même anse, méconnaissable."},{"at":348.61,"end":354.9,"text":"Pour la première fois, on n’a plus à fuir Porto-Vecchio quand vient la chaleur. On peut enfin y passer l’été."}],"cues":{},"pins":{}},{"id":"ete","from":356,"arrive":363,"voice":358.6,"leave":369.82,"lines":[{"at":358.6,"end":365.38,"text":"Alors les saisons se retournent. Pendant trois siècles, l’été vidait la ville ; désormais, il la remplit."},{"at":365.88,"end":368.42,"text":"En une vie d’homme, elle fait plus que tripler."}],"cues":{},"pins":{"habitants":365.88}},{"id":"plages","from":369.82,"arrive":375.82,"voice":371.22,"leave":391,"lines":[{"at":371.22,"end":374.3,"text":"Palombaggia, Santa Giulia, Cala Rossa."},{"at":374.65,"end":381.4,"text":"Là-haut, à l’Ospédale, le lac retient l’eau qui abreuve la côte — la montagne fait toujours vivre la plaine."},{"at":381.9,"end":385.11,"text":"Ceux qui arrivent chaque été refont sans le savoir un très vieux chemin."},{"at":385.56,"end":389.5,"text":"Vous, vous ne venez pas voir cette mer. Vous venez la retrouver."}],"cues":{},"pins":{}},{"id":"soir","from":391,"arrive":399,"voice":393.6,"leave":418.54,"lines":[{"at":393.6,"end":400.51,"text":"Le 31 juillet au soir, on promène dans la vieille ville Luddareddu, « petit juillet », un mannequin de paille et de liège."},{"at":400.91,"end":404.6,"text":"On le juge, on le pend, et à minuit on le brûle devant l’église."},{"at":405.1,"end":409.97,"text":"Juillet était le mois du liège et du sel, celui où les hommes restaient seuls en plaine."},{"at":410.32,"end":417.34,"text":"Le brûler, c’était fêter le droit de remonter. On le brûle toujours, dans une ville où l’on vient désormais passer l’été."}],"cues":{},"pins":{}},{"id":"deux-rues","from":418.54,"arrive":426.54,"voice":421.14,"leave":445.88,"lines":[{"at":421.14,"end":428.07,"text":"Approchez-vous encore. Le long des vieux murs génois, une ruelle porte le nom du docteur Camille de Rocca Serra."},{"at":428.52,"end":432.42,"text":"Au bout, sans même tourner, elle devient la rue du Général-Abbatucci."},{"at":433.02,"end":440.07,"text":"Ce n’est pas un hasard. Le docteur Camille est né à Zicavo, le village des Abbatucci — sa mère portait leur nom."},{"at":440.62,"end":444.28,"text":"Depuis longtemps déjà, la montagne et la mer s’étaient épousées."}],"cues":{},"pins":{}},{"id":"rue","from":445.88,"arrive":456.88,"voice":450.88,"leave":465.02,"lines":[{"at":450.88,"end":455.67,"text":"La voici, à hauteur de pas. Ici, les cartes s’arrêtent sur le seuil."},{"at":456.22,"end":460.95,"text":"Déjà, dans cette rue, des volets se sont rouverts. Car la maison n’oublie rien."},{"at":461.4,"end":463.42,"text":"A casa piglia, a casa rende.","sub":"La maison rend toujours ce qu’elle prend.","kind":"proverb"}],"cues":{},"pins":{}},{"id":"envoi","from":465.02,"arrive":475.02,"voice":470.52,"leave":493.61,"lines":[{"at":470.52,"end":475.21,"text":"La nuit tombe sur Portivechju. Des fenêtres s’allument au-dessus des salines."},{"at":475.76,"end":482.44,"text":"Ici, tout le monde est parti, et tout le monde a retrouvé le chemin — les bergers, les montagnards, Paoli lui-même."},{"at":482.94,"end":488.13,"text":"Si vous écoutez ceci de loin, vous n’êtes pas de passage. Vous êtes le prochain retour."},{"at":488.68,"end":491.61,"text":"Vous ne reconnaîtrez rien, et tout vous reconnaîtra."}],"cues":{},"pins":{}},{"id":"dedicace","from":493.61,"arrive":501.61,"voice":498.11,"leave":510.82,"lines":[{"at":498.11,"end":502.05,"text":"Aux Rocca Serra et aux Abbatucci, et à tous ceux qui en descendent.","quiet":true},{"at":502.9,"end":504.59,"text":"Ici commence toujours le retour.","quiet":true},{"at":505.54,"end":506.82,"text":"Pace è salute.","quiet":true}],"cues":{},"pins":{}}]};
